// Target schema for extracted contact rows (plain JS, no dependencies)
const ContactSchema = {
  name: { type: "string", required: true, minLen: 2 },
  email: { type: "string", required: true, pattern: /^[^\s@]+@[^\s@]+\.[^\s@]+$/ },
  country: { type: "string", required: false },
  hours: { type: "number", required: false, min: 0 },
};
// Schema = the contract; validator below enforces it row by row.

// Validator: per-row error lists (runs anywhere, including the playground)
function validateRow(schema, row) {
  const errors = [];
  for (const [field, rule] of Object.entries(schema)) {
    const v = row[field];
    if (v === undefined || v === null || v === "") {
      if (rule.required) errors.push(`${field}: required but missing`);
      continue;
    }
    if (rule.type === "number" && typeof v !== "number") {
      const n = Number(v);
      if (Number.isNaN(n)) { errors.push(`${field}: expected number, got ${JSON.stringify(v)}`); continue; }
      row[field] = n; // coerce once, centrally, visibly
    }
    if (rule.minLen && String(v).length < rule.minLen) errors.push(`${field}: too short`);
    if (rule.pattern && !rule.pattern.test(String(v))) errors.push(`${field}: format mismatch`);
    if (rule.min !== undefined && v < rule.min) errors.push(`${field}: below minimum ${rule.min}`);
  }
  return errors;
}

// Load with quarantine: clean stream + reasoned rejects (plain JS)
function loadRows(schema, rawRows) {
  const clean = [], quarantined = [];
  for (const raw of rawRows) {
    const row = { ...raw };
    const errors = validateRow(schema, row);
    if (errors.length === 0) clean.push(row);
    else quarantined.push({ row: raw, errors });
  }
  return { clean, quarantined, rejectRate: quarantined.length / rawRows.length };
}
// Report: rejectRate + top error messages = pipeline health at a glance.

