const schema = {
  email: { type: 'string', required: true, pattern: /^[^\s@]+@[^\s@]+\.[^\s@]+$/ },
  hours: { type: 'number', required: false, min: 0 },
};
const batch = [
  { email: 'maya@dev.io', hours: 912 },
  { email: 'not-an-email', hours: 100 },
  { hours: -5 },
  { email: 'jonas@dev.io', hours: 534 },
];
let bad = 0;
for (const row of batch) {
  const errs = validateRow(schema, { ...row });
  if (errs.length) { bad++; console.log('REJECT ' + JSON.stringify(row) + ' -> ' + errs.join('; ')); }
}
console.log('clean: ' + (batch.length - bad) + ', quarantined: ' + bad);

